// Input: ClippyMe completion webhook payload (single item)
// NOTE: webhook node v2 wraps the POST body as {headers, params, query, body}
const raw = $input.first().json;
const body = raw && raw.body ? raw.body : raw;

// 1. Only completed jobs
if (body.status !== 'completed') {
  return [];
}

// 2. Per-clip gate: viral_score >= 85 AND not already published
const clips = Array.isArray(body.clips) ? body.clips : [];
const picked = clips.filter((c) => {
  const score = typeof c.viral_score === 'number' ? c.viral_score : Number(c.viral_score);
  return Number.isFinite(score) && score >= 85 && !c.published;
});

return picked.map((c) => ({ json: c }));

// Multi-account routing (publish targets V1).
// LANGUAGE FALLBACK DISABLED (2026-11-11, user decision: only ONE Google account
// for now) — without explicit targets everything goes to 'youtube-default'.
// Re-enable by flipping ENABLE_PL_ROUTE=true AFTER connecting credential #2
// ('yt-kanal-a'), otherwise Polish clips ERROR on the placeholder credential.
// Input: 1 item per qualifying clip (from "Filter clips").
// Routing: clip.targets (per-clip override) || payload-level targets
//          || LANGUAGE: Polish title/description -> "yt-kanal-a", else "youtube-default".
// Job-level targets live on the webhook payload (v2 body wrap), not on the
// filtered clip items — hence the re-read from "Job completed".
const rawWebhook = $('Job completed').first().json;
const body = rawWebhook && rawWebhook.body ? rawWebhook.body : (rawWebhook || {});
const ENABLE_PL_ROUTE = false; // flip to true when credential #2 is connected
const slugOk = (t) => typeof t === 'string' && /^[a-z0-9_-]{1,40}$/.test(t);
let jobTargets = Array.isArray(body.targets) ? body.targets.filter(slugOk) : [];

// Polish detector: PL diacritics + frequent Polish function words.
const isPolish = (s) => {
  if (!s) return false;
  if (/[\u0105\u0107\u0119\u0142\u0144\u00f3\u015b\u017a\u017c\u0104\u0106\u0118\u0141\u0143\u00d3\u015a\u0179\u017b]/.test(s)) return true;
  return /\b(si\u0119|jest|nie|jak|ten|tak|ale|ju\u017c|czy|dlaczego|kt\u00f3ry|wszystko|mo\u017ce)\b/i.test(s);
};

const out = [];
for (const item of $input.all()) {
  const clip = item.json;
  let targets = Array.isArray(clip.targets) && clip.targets.length
    ? clip.targets.filter(slugOk)
    : jobTargets;
  if (!targets.length) {
    if (ENABLE_PL_ROUTE) {
      const text = [clip.title, clip.description].filter(Boolean).join(' ');
      targets = [isPolish(text) ? 'yt-kanal-a' : 'youtube-default'];
    } else {
      targets = ['youtube-default'];
    }
  }
  for (const t of [...new Set(targets)]) {
    out.push({ json: { ...clip, clippy_target: t } });
  }
}
return out;

